begin;
do $curate$ declare bid uuid; begin
if exists(select 1 from public.businesses where website ilike '%zanyentertainment%' or name ilike '%zany entertainment%' or regexp_replace(coalesce(phone,''),'[^0-9]','','g') like '%2098358383') then raise exception 'Duplicate provider requires review';end if;
insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('Zany Entertainment','Entertainment','Tracy','1005 E Pescadero Ave, Unit 167, Tracy, CA 95304','(209) 835-8383','https://zanyentertainment.com/','Advertises magic shows, clown entertainment and balloon twisting for birthdays, festivals, schools and libraries. Website lists a Tracy contact address and separate performer phone numbers; the main listed contact here is Sparkles. Confirm travel coverage, suitability, quote and scheduling directly. No additional city service area established.','approved',true,false,null,0,'editorial_first_party','https://zanyentertainment.com/','first_party_website_desk_check',now()) returning id into bid;
insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://zanyentertainment.com/',array['identity','public phone','website','contact address','advertised services'],array['Tracy'],array['party entertainment','magic shows','balloon twisting'],'Official website confirms Tracy contact address, Sparkles phone and advertised entertainment. Contact address may not be a visitor venue. Additional city coverage, credentials, suitability, quality and availability not independently verified. Newspaper lead page28; no images reused.');
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,'{"name":"Zany Entertainment","source":"https://zanyentertainment.com/","city":"Tracy","phone":"(209) 835-8383","address":"1005 E Pescadero Ave, Unit 167, Tracy, CA 95304","description":"Advertises magic shows, clown entertainment and balloon twisting for birthdays, festivals, schools and libraries. Website lists a Tracy contact address and separate performer phone numbers; the main listed contact here is Sparkles. Confirm travel coverage, suitability, quote and scheduling directly. No additional city service area established."}'::jsonb,'Newspaper lead independently checked against first-party website','https://zanyentertainment.com/');
end $curate$;
do $recheck$ declare old jsonb;begin
select to_jsonb(b) into old from public.businesses b where id='4176afc1-6005-4240-9f86-e7b8c0567699' for update;
update public.businesses set verification_source='first_party_website_desk_check',verified_at=now() where id='4176afc1-6005-4240-9f86-e7b8c0567699';
insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values('4176afc1-6005-4240-9f86-e7b8c0567699','https://order.toasttab.com/online/t-hub-cafe-mountain-house-1158-tradition-street',array['identity','website','address','public phone','menu categories'],array['Mountain House'],array['cafe','boba tea','coffee','biryani'],'Cafe official website links this ordering page, confirming 1158 Tradition Street and phone. Conflicting newspaper 1140/#158 address not adopted. Menu categories checked; prices, live hours, dietary claims, quality and availability not certified. No photos copied.') on conflict(business_id) do update set checked_at=now(),source_url=excluded.source_url,checked_fields=excluded.checked_fields,service_areas=excluded.service_areas,service_tags=excluded.service_tags,scope_note=excluded.scope_note;
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values('4176afc1-6005-4240-9f86-e7b8c0567699',old,'{"id":"4176afc1-6005-4240-9f86-e7b8c0567699","name":"THub Cafe","source":"https://order.toasttab.com/online/t-hub-cafe-mountain-house-1158-tradition-street","result":"Official cafe website links this ordering page; it confirms existing 1158 Tradition Street address and (209)989-8482. Newspaper''s 1140/#158 address not adopted."}'::jsonb,'Retain current address after resolving newspaper conflict against cafe-linked ordering source','https://order.toasttab.com/online/t-hub-cafe-mountain-house-1158-tradition-street');
