insert into public.events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'Veterans Liberty Garden Ribbon Cutting','City ceremony honoring veterans at the new Liberty Garden. The official Form Center lists November 14 at 11 AM and requests an RSVP to help plan attendance and seating. Check the city page for arrangements and any changes. End time not confirmed.','Mountain House','Veterans Liberty Garden, end of Grand Avenue west of Safeway, near Raphael Street, Mountain House','2026-11-14T11:00:00-08:00',null,'Community programs','https://www.mountainhouseca.gov/FormCenter/RSVPs-8/Veterans-Liberty-Garden-Ribbon-Cutting-R-69','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from public.events where city='Mountain House' and source_url='https://www.mountainhouseca.gov/FormCenter/RSVPs-8/Veterans-Liberty-Garden-Ribbon-Cutting-R-69' and start_date='2026-11-14T11:00:00-08:00'::timestamptz);
insert into public.events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'A Salute to Service: Veterans Day Luncheon','City luncheon honoring veterans. Official Form Center lists November 14 at noon in Town Hall''s Lobby and Board Room. RSVP through the city; seating is limited. Confirm attendance and end time directly. MoHoLocal does not reserve a place.','Mountain House','Mountain House Town Hall, Lobby and Board Room, 251 E Main Street, Mountain House','2026-11-14T12:00:00-08:00',null,'Community programs','https://www.mountainhouseca.gov/FormCenter/RSVPs-8/A-Salute-to-Service-Veterans-Day-Luncheo-70','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from public.events where city='Mountain House' and source_url='https://www.mountainhouseca.gov/FormCenter/RSVPs-8/A-Salute-to-Service-Veterans-Day-Luncheo-70' and start_date='2026-11-14T12:00:00-08:00'::timestamptz);
